(function(r){'use strict';let attempts=0;function mount(){if(++attempts>120)return;const live=r.PrecisionLab265?.state?.g,bar=[...document.querySelectorAll('button')].find(b=>b.textContent==='Restart duel')?.parentElement;if(!live?.practice278||!bar){setTimeout(mount,500);return;}if(live.player.type!=='niko')return;const N=r.NeonCombat,box=document.createElement('details');box.style.cssText='position:fixed;right:16px;top:80px;z-index:10020;width:min(680px,92vw);max-height:75vh;overflow:auto;background:#111c2a;color:#e0f3fa;padding:12px;border:1px solid #5897a8';box.innerHTML='<summary>Leg-lock animation gallery · all opponents</summary><p>Offline native capture and move; fixed frame and full-body textures. The live battle is unchanged.</p><label>Animation opponent <select aria-label="Animation opponent"></select></label> <label>Move frame <input aria-label="Leg-lock frame" type="range" min="0" max="131" value="0"></label><p data-caption></p><canvas width="640" height="300" aria-label="Synchronized leg-lock frame"></canvas>';bar.parentElement.append(box);const sel=box.querySelector('select'),slider=box.querySelector('input'),canvas=box.querySelector('canvas'),c=canvas.getContext('2d');canvas.style.width='100%';canvas.style.maxWidth='640px';for(const q of N.Practice278.options(live).filter(q=>q.available)){const o=document.createElement('option');o.value=q.id;o.textContent=q.name;sel.append(o);}function draw(){const g=new N.Brawler();g.selectHero('niko');N.Practice282.setup(g,{id:sel.value});g.ai=g.tryGrab=()=>{};const p=g.player,v=g.enemies[0];Object.assign(p,{x:250,y:480,prevX:250,prevY:480,dir:1,cd:0,inv:0});Object.assign(v,{x:295,y:480,dir:-1,hp:Math.min(50,v.maxHp*.2),inv:0,wakeInv:0,grabImmune:0,activeAt:0});g.bossProtected=()=>false;g.grabRandom198={next:()=>.99};if(!g.acquireGrab(v,false)){box.querySelector('[data-caption]').textContent='Capture rejected by native rules';return;}p.act=null;p.cd=0;N.Niko185.beginPair(g,'throat',v);g.nikoRandom185={next:()=>.99};N.LegThrow286.visual(g,p.act);for(let i=0;i<+slider.value;i++)g.tick(1/60,{});c.fillStyle='#111c2a';c.fillRect(0,0,640,300);c.strokeStyle='#557085';c.beginPath();c.moveTo(0,260);c.lineTo(640,260);c.stroke();for(const f of[v,p]){c.save();c.translate(f.x,f.y-220);c.scale(f.dir*N.Forest125.scale(f),N.Forest125.scale(f));r.PolishedSprites.draw(c,f,0,1);c.restore();}c.save();c.translate(0,-220);r.ReviewView287.foreground(c,g);c.restore();box.querySelector('[data-caption]').textContent='Frame '+slider.value+' / 132 · '+p.leg286?.phase+' · '+v.name+' · common ground line';}sel.onchange=slider.oninput=draw;box.ontoggle=()=>{if(box.open)draw()};}setTimeout(mount,2500);})(globalThis);
